:root {
  --bg: #0f1220;
  --panel: #191d31;
  --panel-2: #222741;
  --text: #e7e9f3;
  --muted: #9aa0bd;
  --accent: #6c8cff;
  --accent-2: #4b6bff;
  --danger: #ff6b7a;
  --border: #2a2f4a;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 20px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 5;
}
.topbar h1 { font-size: 20px; margin: 0; white-space: nowrap; }
.search { flex: 1; }
.search input {
  width: 100%;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 14px;
}

button {
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  padding: 10px 14px;
  border-radius: 10px;
  font-size: 14px;
}
button.primary { background: var(--accent-2); border-color: var(--accent-2); }
button.primary:hover { background: var(--accent); }

.layout { display: flex; align-items: flex-start; }
.sidebar {
  width: 220px;
  padding: 20px;
  border-right: 1px solid var(--border);
  min-height: calc(100vh - 57px);
}
.sidebar h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); }
.tag-list { list-style: none; padding: 0; margin: 0; }
.tag-list li {
  display: flex;
  justify-content: space-between;
  padding: 7px 10px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 14px;
}
.tag-list li:hover, .tag-list li.active { background: var(--panel-2); }
.tag-list .count { color: var(--muted); font-size: 12px; }

.content { flex: 1; padding: 20px; }
.active-filter {
  margin-bottom: 14px;
  color: var(--muted);
  font-size: 14px;
}
.active-filter button { padding: 4px 10px; margin-left: 8px; font-size: 12px; }

.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 14px; }
.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.card a.title { color: var(--text); font-weight: 600; text-decoration: none; font-size: 16px; }
.card a.title:hover { color: var(--accent); }
.card .url { color: var(--muted); font-size: 12px; word-break: break-all; }
.card .desc { font-size: 14px; color: #c7cbe4; }
.card .tags { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; }
.card .tag {
  background: var(--panel-2);
  color: var(--accent);
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  cursor: pointer;
}
.card .actions { display: flex; gap: 8px; margin-top: 6px; }
.card .actions button { padding: 6px 10px; font-size: 12px; }
.card .actions .del:hover { border-color: var(--danger); color: var(--danger); }

.empty { color: var(--muted); text-align: center; margin-top: 60px; }

.modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 20;
}
.modal-box {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 24px;
  width: min(460px, 92vw);
}
.modal-box h2 { margin-top: 0; }
.modal form { display: flex; flex-direction: column; gap: 12px; }
.modal label { display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--muted); }
.modal input, .modal textarea {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}
.req { color: var(--danger); }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }

@media (max-width: 720px) {
  .layout { flex-direction: column; }
  .sidebar { width: 100%; min-height: auto; border-right: none; border-bottom: 1px solid var(--border); }
}

